using System.IO;
using System.Text.Json;
using VisionPluginContracts;
static class Program{
 static int checks;static void Check(bool test,string label){checks++;if(!test)throw new Exception(label);}
 [STAThread]static int Main(){try{Run();Console.WriteLine($"VisionConfiguration.InteractionChecks: {checks} checks passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(){var root=Path.Combine(Path.GetTempPath(),"VisionConfiguration-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var a=Path.Combine(root,"a");var b=Path.Combine(root,"b");Directory.CreateDirectory(a);Directory.CreateDirectory(b);var fileA=Path.Combine(a,"a.xml");var fileB=Path.Combine(b,"b.xml");File.WriteAllText(fileA,"<test/>");File.WriteAllText(fileB,"<test/>");
  var store=new ConfigurationFileHistory(Path.Combine(root,"history"));ConfigurationFilePickerOptions? options=null;int picked=0;var service=new WpfConfigurationFileService(store,(_,o)=>{options=o;picked++;return new(ConfigurationFileStatus.Selected,[fileA]);});var request=new ConfigurationFileRequest("module-a","","XML|*.xml","Open");
  Check(service.Select(null,request).Status==ConfigurationFileStatus.Selected,"existing file selected");Check(options is {InitialDirectory:"",CheckFileExists:true,CheckPathExists:true,Multiselect:false},"source picker flags");Check(!File.Exists(store.StoragePath),"select does not prematurely write history");Check(service.Remember("module-a",fileA).Success,"remember after caller set");Check(new ConfigurationFileHistory(Path.Combine(root,"history")).Get("module-a").Directory==a,"history persisted across service instances");
  service.Select(null,request);Check(options!.InitialDirectory==a,"stored directory used");service.Select(null,request with{CurrentPath=fileB});Check(options!.InitialDirectory==b,"current existing file directory overrides history");service.Select(null,request with{ModuleKey="other-module"});Check(options!.InitialDirectory=="","per-module isolation");
  var before=picked;Check(service.Select(null,request with{Remote=true}).Status==ConfigurationFileStatus.Unsupported&&picked==before,"remote unsupported no local fallback");var cancel=new WpfConfigurationFileService(store,(_,_)=>new(ConfigurationFileStatus.Cancelled,[]));Check(cancel.Select(null,request).Status==ConfigurationFileStatus.Cancelled,"cancel preserved");Check(store.Get("module-a").Directory==a,"cancel no history mutation");
  var invalid=new WpfConfigurationFileService(store,(_,_)=>new(ConfigurationFileStatus.Selected,[Path.Combine(root,"missing.xml")]));Check(invalid.Select(null,request).Status==ConfigurationFileStatus.Failed,"nonexistent injected selection rejected");var throwing=new WpfConfigurationFileService(store,(_,_)=>throw new IOException("picker-error"));Check(throwing.Select(null,request).Diagnostic=="picker-error","picker exception diagnosed");
  Task.WaitAll(Task.Run(()=>new ConfigurationFileHistory(Path.Combine(root,"history")).Remember("parallel-a",fileA)),Task.Run(()=>new ConfigurationFileHistory(Path.Combine(root,"history")).Remember("parallel-b",fileB)));Check(store.Get("parallel-a").Directory==a&&store.Get("parallel-b").Directory==b,"shared path locking no lost module update");
  File.WriteAllText(store.StoragePath,"broken");Check(!store.Get("module-a").Success,"corrupt history explicit failure");Check(service.Select(null,request).Status==ConfigurationFileStatus.Failed,"corrupt history not guessed");
  var obstructed=Path.Combine(root,"obstructed");File.WriteAllText(obstructed,"file blocks directory");Check(!new ConfigurationFileHistory(obstructed).Remember("module-a",fileA).Success,"actual history write failure explicit");
  var events=new List<string>();var notifications=new WpfConfigurationNotificationService((_,message)=>events.Add(message.Kind+":"+message.Message));Check(notifications.Notify(null,new(ConfigurationNotificationKind.Success,"done")).Status==ConfigurationNotificationStatus.Displayed,"success presenter invoked");Check(events.Single()=="Success:done","notification payload intact");Check(notifications.Notify(null,new(ConfigurationNotificationKind.Error,"bad",Mode:ToolEditorMode.SdkEmbedded)).Status==ConfigurationNotificationStatus.Suppressed&&events.Count==1,"source SDK suppression");var failed=new WpfConfigurationNotificationService((_,_)=>throw new InvalidOperationException("notify-error"));Check(failed.Notify(null,new(ConfigurationNotificationKind.Error,"bad")).Diagnostic=="notify-error","notification failure explicit");
  foreach(var language in new[]{"Chinese","English"})foreach(var key in new[]{"Open","Lang_SetSuc","Lang_FileOpenFail","Lang_SysErr"})Check(ConfigurationLocalization.ForLanguage(language).TryGet(key,out var caption)&&!string.IsNullOrEmpty(caption),"original localized key "+key);
 }
}
